    path1.lineTo(heartX, heartY + 120*s);
    path1.lineTo(heartX + 80*s, heartY + 50*s);
    path1.cubicTo(heartX + 110*s, heartY + 20*s, heartX + 110*s, heartY - 20*s, heartX + 80*s, heartY - 50*s);
