import { useState, useEffect } from 'react'

/**
 * Custom hook to load and manage the WebAssembly graphics module
 */
export function useWasmModule() {
  const [module, setModule] = useState(null)
  const [canvas, setCanvas] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  useEffect(() => {
    let mounted = true

    async function loadWasm() {
      try {
        // Load the Emscripten-generated JS file
        // It will automatically load the .wasm file
        const script = document.createElement('script')
        script.src = '/graphics_engine.js'
        script.async = true

        script.onload = () => {
          // Wait for Module to be ready
          if (window.Module) {
            window.Module.onRuntimeInitialized = () => {
              if (mounted) {
                setModule(window.Module)
                setLoading(false)
              }
            }
          }
        }

        script.onerror = () => {
          if (mounted) {
            setError('Failed to load WASM module')
            setLoading(false)
          }
        }

        document.body.appendChild(script)

        return () => {
          mounted = false
          if (script.parentNode) {
            script.parentNode.removeChild(script)
          }
        }
      } catch (err) {
        if (mounted) {
          setError(err.message)
          setLoading(false)
        }
      }
    }

    loadWasm()
  }, [])

  const createCanvas = (width, height) => {
    if (!module || canvas) return canvas

    const newCanvas = new module.CanvasWrapper(width, height)
    setCanvas(newCanvas)
    return newCanvas
  }

  const deleteCanvas = () => {
    if (canvas) {
      canvas.delete()
      setCanvas(null)
    }
  }

  return {
    module,
    canvas,
    loading,
    error,
    createCanvas,
    deleteCanvas
  }
}

