import React, { useEffect, useRef, useState } from 'react'
import { useWasmModule } from '../hooks/useWasmModule'

function GraphicsWasmPage() {
  const { module: Module, loading, error } = useWasmModule()
  const canvasRef = useRef(null)
  const wasmCanvasRef = useRef(null)
  const [selectedDemo, setSelectedDemo] = useState('shapes')

  useEffect(() => {
    if (!Module || !canvasRef.current) return

    // Initialize WASM canvas
    const wasmCanvas = new Module.CanvasWrapper(800, 600)
    wasmCanvasRef.current = wasmCanvas

    // Initial draw
    runDemo(selectedDemo)

    return () => {
      if (wasmCanvas) {
        wasmCanvas.delete()
      }
    }
  }, [Module])

  useEffect(() => {
    if (wasmCanvasRef.current) {
      runDemo(selectedDemo)
    }
  }, [selectedDemo])

  const runDemo = (demoName) => {
    const wasmCanvas = wasmCanvasRef.current
    if (!wasmCanvas || !Module) return

    try {
      switch (demoName) {
        case 'shapes':
          drawShapes(wasmCanvas)
          break
        case 'transforms':
          drawTransforms(wasmCanvas)
          break
        case 'gradients':
          drawGradients(wasmCanvas)
          break
        case 'blend-modes':
          drawBlendModes(wasmCanvas)
          break
        case 'paths':
          drawPaths(wasmCanvas)
          break
        default:
          drawShapes(wasmCanvas)
      }

      updateCanvasDisplay()
    } catch (err) {
      console.error('Demo error:', err)
    }
  }

  const drawShapes = (wasmCanvas) => {
    wasmCanvas.clear(0.95, 0.95, 0.95, 1.0)

    // Blue rectangle
    wasmCanvas.drawRect(50, 50, 200, 150, 0.2, 0.4, 0.8, 1.0)

    // Red circle (using path)
    const circle = new Module.PathWrapper()
    circle.addCircle(450, 125, 80, Module.PathDirection.CW)
    const paint = new Module.PaintWrapper()
    paint.setColor(0.9, 0.2, 0.2, 1.0)
    wasmCanvas.drawPathWithPaint(circle, paint)
    circle.delete()
    paint.delete()

    // Green triangle
    const triangle = new Module.PathWrapper()
    triangle.moveTo(400, 300)
    triangle.lineTo(500, 500)
    triangle.lineTo(300, 500)
    triangle.close()
    const paint2 = new Module.PaintWrapper()
    paint2.setColor(0.2, 0.8, 0.2, 1.0)
    wasmCanvas.drawPathWithPaint(triangle, paint2)
    triangle.delete()
    paint2.delete()
  }

  const drawTransforms = (wasmCanvas) => {
    wasmCanvas.clear(1.0, 1.0, 1.0, 1.0)

    // Original rectangle
    wasmCanvas.drawRect(50, 50, 100, 100, 0.8, 0.2, 0.2, 0.5)

    // Translated rectangle
    wasmCanvas.save()
    wasmCanvas.translate(200, 0)
    wasmCanvas.drawRect(50, 50, 100, 100, 0.2, 0.8, 0.2, 0.5)
    wasmCanvas.restore()

    // Rotated rectangle
    wasmCanvas.save()
    wasmCanvas.translate(450, 100)
    wasmCanvas.rotate(45 * Math.PI / 180)
    wasmCanvas.drawRect(-50, -50, 100, 100, 0.2, 0.2, 0.8, 0.5)
    wasmCanvas.restore()

    // Scaled rectangle
    wasmCanvas.save()
    wasmCanvas.translate(150, 350)
    wasmCanvas.scale(2.0, 1.5)
    wasmCanvas.drawRect(-25, -25, 50, 50, 0.8, 0.8, 0.2, 0.5)
    wasmCanvas.restore()
  }

  const drawGradients = (wasmCanvas) => {
    wasmCanvas.clear(0.1, 0.1, 0.1, 1.0)

    // Linear gradient
    const colors = new Module.VectorFloat()
    ;[1.0, 0.2, 0.5, 1.0, 0.2, 0.5, 1.0, 1.0, 1.0, 0.9, 0.2, 1.0].forEach(v => colors.push_back(v))

    const shader = Module.createLinearGradient(50, 100, 350, 500, colors, Module.TileMode.Clamp)
    const paint = new Module.PaintWrapper()
    paint.setShader(shader.getPtr())
    wasmCanvas.drawRectWithPaint(50, 100, 300, 400, paint)

    colors.delete()
    paint.delete()
    shader.delete()
  }

  const drawBlendModes = (wasmCanvas) => {
    wasmCanvas.clear(1.0, 1.0, 1.0, 1.0)

    // Blue circle (destination)
    const circle1 = new Module.PathWrapper()
    circle1.addCircle(350, 300, 100, Module.PathDirection.CW)
    const paint1 = new Module.PaintWrapper()
    paint1.setColor(0.2, 0.5, 1.0, 0.7)
    wasmCanvas.drawPathWithPaint(circle1, paint1)
    circle1.delete()
    paint1.delete()

    // Red circle (source) with blend mode
    const circle2 = new Module.PathWrapper()
    circle2.addCircle(450, 300, 100, Module.PathDirection.CW)
    const paint2 = new Module.PaintWrapper()
    paint2.setColor(1.0, 0.3, 0.3, 0.7)
    paint2.setBlendMode(Module.BlendMode.Multiply)
    wasmCanvas.drawPathWithPaint(circle2, paint2)
    circle2.delete()
    paint2.delete()
  }

  const drawPaths = (wasmCanvas) => {
    wasmCanvas.clear(1.0, 1.0, 1.0, 1.0)

    // Heart shape using cubic curves
    const heart = new Module.PathWrapper()
    const hx = 200, hy = 200, s = 1.0
    heart.moveTo(hx, hy)
    heart.cubicTo(hx, hy - 50*s, hx - 50*s, hy - 80*s, hx - 80*s, hy - 50*s)
    heart.cubicTo(hx - 110*s, hy - 20*s, hx - 110*s, hy + 20*s, hx - 80*s, hy + 50*s)
    heart.lineTo(hx, hy + 120*s)
    heart.lineTo(hx + 80*s, hy + 50*s)
    heart.cubicTo(hx + 110*s, hy + 20*s, hx + 110*s, hy - 20*s, hx + 80*s, hy - 50*s)
    heart.cubicTo(hx + 50*s, hy - 80*s, hx, hy - 50*s, hx, hy)

    const paint = new Module.PaintWrapper()
    paint.setColor(0.93, 0.3, 0.22, 1.0)
    wasmCanvas.drawPathWithPaint(heart, paint)
    heart.delete()
    paint.delete()

    // Star using lines
    const star = new Module.PathWrapper()
    const sx = 550, sy = 250, outerR = 100, innerR = 40
    for (let i = 0; i < 5; i++) {
      const angle = (i * Math.PI * 2) / 5 - Math.PI / 2
      const x = sx + outerR * Math.cos(angle)
      const y = sy + outerR * Math.sin(angle)

      if (i === 0) star.moveTo(x, y)
      else star.lineTo(x, y)

      const innerAngle = angle + Math.PI / 5
      const ix = sx + innerR * Math.cos(innerAngle)
      const iy = sy + innerR * Math.sin(innerAngle)
      star.lineTo(ix, iy)
    }

    const paint2 = new Module.PaintWrapper()
    paint2.setColor(1.0, 0.84, 0.0, 1.0)
    wasmCanvas.drawPathWithPaint(star, paint2)
    star.delete()
    paint2.delete()
  }

  const updateCanvasDisplay = () => {
    const wasmCanvas = wasmCanvasRef.current
    if (!wasmCanvas || !canvasRef.current) return

    const canvas = canvasRef.current
    const ctx = canvas.getContext('2d')
    const buffer = wasmCanvas.getBuffer()
    const width = wasmCanvas.getWidth()
    const height = wasmCanvas.getHeight()

    const imageData = ctx.createImageData(width, height)
    imageData.data.set(buffer)
    ctx.putImageData(imageData, 0, 0)
  }

  const demos = [
    { id: 'shapes', name: 'Basic Shapes' },
    { id: 'transforms', name: 'Transformations' },
    { id: 'gradients', name: 'Linear Gradients' },
    { id: 'blend-modes', name: 'Blend Modes' },
    { id: 'paths', name: 'Curved Paths' }
  ]

  return (
    <>
      <style>{`
        body {
          background: linear-gradient(135deg, #2E7D32 0%, #1B5E20 100%);
          min-height: 100vh;
          padding: 2rem;
        }

        .wasm-page {
          max-width: 1400px;
          margin: 0 auto;
          background: white;
          border-radius: 12px;
          box-shadow: 0 20px 60px rgba(0,0,0,0.3);
          overflow: hidden;
        }

        .wasm-header {
          background: linear-gradient(135deg, #2c3e50 0%, #34495e 100%);
          color: white;
          padding: 2rem;
          text-align: center;
        }

        .wasm-header h1 {
          margin-bottom: 0.5rem;
        }

        .wasm-header .badge {
          display: inline-block;
          background: #2E7D32;
          color: white;
          padding: 0.25rem 0.75rem;
          border-radius: 12px;
          font-size: 0.85rem;
          margin-top: 0.5rem;
        }

        .wasm-content {
          display: grid;
          grid-template-columns: 320px 1fr;
          gap: 2rem;
          padding: 2rem;
        }

        .wasm-controls {
          background: #f8f9fa;
          padding: 1.5rem;
          border-radius: 8px;
        }

        .control-group {
          margin-bottom: 1.5rem;
        }

        .control-group label {
          display: block;
          font-weight: 600;
          margin-bottom: 0.5rem;
          color: #2c3e50;
        }

        .control-group select {
          width: 100%;
          padding: 0.5rem;
          border: 1px solid #ddd;
          border-radius: 4px;
          font-size: 1rem;
        }

        .canvas-container {
          background: #f0f0f0;
          border-radius: 8px;
          padding: 1rem;
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          min-height: 600px;
        }

        #canvas {
          background: white;
          border: 2px solid #ddd;
          box-shadow: 0 4px 6px rgba(0,0,0,0.1);
        }

        .status {
          padding: 1rem;
          border-radius: 6px;
          margin-bottom: 1rem;
          text-align: center;
          font-weight: 600;
        }

        .status.loading {
          background: #fff3cd;
          border: 2px solid #ffc107;
          color: #856404;
        }

        .status.success {
          background: #d4edda;
          border: 2px solid #28a745;
          color: #155724;
        }

        .status.error {
          background: #f8d7da;
          border: 2px solid #dc3545;
          color: #721c24;
        }

        .info {
          background: #e8f4f8;
          padding: 1rem;
          border-radius: 4px;
          margin-bottom: 1rem;
          font-size: 0.9rem;
        }

        @media (max-width: 900px) {
          .wasm-content {
            grid-template-columns: 1fr;
          }
        }
      `}</style>

      <div className="wasm-page">
        <header className="wasm-header">
          <h1>C++ Graphics Engine (WebAssembly)</h1>
          <p>Real C++ code compiled to WebAssembly running in your browser</p>
          <span className="badge">Powered by Emscripten</span>
        </header>

        <div className="wasm-content">
          <aside className="wasm-controls">
            <div className="control-group">
              <label>Select Demo:</label>
              <select value={selectedDemo} onChange={(e) => setSelectedDemo(e.target.value)}>
                {demos.map(demo => (
                  <option key={demo.id} value={demo.id}>{demo.name}</option>
                ))}
              </select>
            </div>

            <div className="info">
              <strong>About this demo:</strong>
              <p style={{ marginTop: '0.5rem' }}>
                This is actual C++ code compiled to WebAssembly. The graphics engine is written in C++
                and compiled using Emscripten to run natively in your browser at near-native speed.
              </p>
            </div>
          </aside>

          <div className="canvas-container">
            {loading && (
              <div className="status loading">
                Loading WebAssembly module...
              </div>
            )}

            {error && (
              <div className="status error">
                Error: {error}
              </div>
            )}

            {!loading && !error && (
              <div className="status success">
                WASM Module Loaded Successfully ✓
              </div>
            )}

            <canvas
              ref={canvasRef}
              id="canvas"
              width="800"
              height="600"
              style={{ display: loading || error ? 'none' : 'block' }}
            />
          </div>
        </div>
      </div>
    </>
  )
}

export default GraphicsWasmPage

