   586→        // Utility: Convert hex color to RGBA
   587→        function hexToRGBA(hex, alpha = 1.0) {
   588→            const r = parseInt(hex.substr(1, 2), 16) / 255;
   589→            const g = parseInt(hex.substr(3, 2), 16) / 255;
   590→            const b = parseInt(hex.substr(5, 2), 16) / 255;
   591→            return { r, g, b, a: alpha };
   592→        }
   593→
   594→        // Get numeric parameter value
   595→        function getParam(demoName, groupName, paramName, defaultValue = 0) {
   596→            const fullName = `${demoName}_${groupName}_${paramName}`;
   597→            const value = currentParams[fullName];
   598→            return value !== undefined ? parseFloat(value) : defaultValue;
   599→        }
   600→
   601→        // Get color parameter as RGBA object
   602→        function getColorParam(demoName, groupName, paramName, defaultHex = '#ffffff') {
   603→            const fullName = `${demoName}_${groupName}_${paramName}`;
   604→            const hex = currentParams[fullName] || defaultHex;
   605→            return hexToRGBA(hex);
   606→        }
