   614→        // Convert tile mode string to numeric enum value
   615→        function getTileModeValue(tileModeName) {
   616→            const tileModeMap = {
   617→                'Clamp': 0,   // GTileMode::kClamp
   618→                'Repeat': 1,  // GTileMode::kRepeat
   619→                'Mirror': 2   // GTileMode::kMirror
   620→            };
   621→            return tileModeMap[tileModeName] !== undefined ? tileModeMap[tileModeName] : 0;
   622→        }
   623→
   624→        // Format group name for display (e.g., 'blueRect' -> 'Blue Rectangle')
   625→        function formatGroupName(name) {
   626→            return name.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase());
   627→        }
   628→
   629→        // Generate HTML for a single control input
   630→        function generateControlHTML(name, config) {
   631→            switch (config.type) {
   632→                case 'range':
   633→                    return `
   634→                        <div class="control-item">
   635→                            <label for="${name}">${config.label}</label>
   636→                            <div class="range-wrapper">
   637→                                <input type="range" id="${name}"
   638→                                       min="${config.min}" max="${config.max}"
   639→                                       step="${config.step}" value="${config.default}"
   640→                                       data-param="${name}">
   641→                                <span class="range-value" id="${name}_value">${config.default}</span>
   642→                            </div>
   643→                        </div>
   644→                    `;
   645→
   646→                case 'color':
   647→                    return `
   648→                        <div class="control-item">
   649→                            <label for="${name}">${config.label}</label>
   650→                            <div class="color-wrapper">
   651→                                <input type="color" id="${name}"
   652→                                       value="${config.default}"
   653→                                       data-param="${name}">
   654→                                <input type="text" id="${name}_hex"
   655→                                       value="${config.default}"
   656→                                       class="color-hex" readonly>
   657→                            </div>
   658→                        </div>
   659→                    `;
   660→
   661→                case 'select':
   662→                    const options = config.options.map(opt =>
   663→                        `<option value="${opt}" ${opt === config.default ? 'selected' : ''}>${opt}</option>`
   664→                    ).join('');
   665→                    return `
   666→                        <div class="control-item">
   667→                            <label for="${name}">${config.label}</label>
   668→                            <select id="${name}" data-param="${name}">
   669→                                ${options}
   670→                            </select>
   671→                        </div>
   672→                    `;
   673→            }
   674→        }
   675→
   676→        // Generate controls HTML for a demo
   677→        function generateControlsForDemo(demoName) {
   678→            const params = demoParameters[demoName];
   679→            if (!params) return '';
   680→
   681→            let html = '';
   682→
   683→            // Iterate through parameter groups (e.g., rect1, rect2, triangle)
   684→            for (const [groupName, groupParams] of Object.entries(params)) {
   685→                html += `<div class="param-group">`;
   686→                html += `<h4 class="param-group-title">${formatGroupName(groupName)}</h4>`;
   687→
   688→                // Iterate through individual parameters
   689→                for (const [paramName, config] of Object.entries(groupParams)) {
   690→                    const fullName = `${demoName}_${groupName}_${paramName}`;
   691→                    html += generateControlHTML(fullName, config);
   692→
   693→                    // Initialize currentParams with default value
   694→                    if (currentParams[fullName] === undefined) {
   695→                        currentParams[fullName] = config.default;
   696→                    }
   697→                }
   698→
   699→                html += `</div>`;
   700→            }
   701→
   702→            return html;
   703→        }
