   738→        function updateCanvasDisplay() {
   739→            if (!wasmCanvas || !Module) return;
   740→
   741→            try {
   742→                const width = wasmCanvas.getWidth();
   743→                const height = wasmCanvas.getHeight();
   744→                const pixelPtr = wasmCanvas.getPixelsPtr();
   745→                const pixelCount = width * height;
   746→
   747→                let wasmPixels;
   748→                if (Module.HEAPU32) {
   749→                    wasmPixels = new Uint32Array(Module.HEAPU32.buffer, pixelPtr, pixelCount);
   750→                } else if (Module.HEAPU8) {
   751→                    wasmPixels = new Uint32Array(Module.HEAPU8.buffer, pixelPtr, pixelCount);
   752→                }
   753→
   754→                const imageData = ctx.createImageData(width, height);
   755→                const data = imageData.data;
   756→
   757→                // Convert premultiplied ARGB to non-premultiplied RGBA
   758→                for (let i = 0; i < pixelCount; i++) {
   759→                    const argb = wasmPixels[i];
   760→                    const a = (argb >> 24) & 0xFF;
   761→                    let r = (argb >> 16) & 0xFF;
   762→                    let g = (argb >> 8) & 0xFF;
   763→                    let b = argb & 0xFF;
   764→
   765→                    // Unpremultiply RGB by alpha
   766→                    if (a > 0 && a < 255) {
   767→                        r = Math.round((r * 255) / a);
   768→                        g = Math.round((g * 255) / a);
   769→                        b = Math.round((b * 255) / a);
   770→                    }
   771→
   772→                    const idx = i * 4;
   773→                    data[idx] = r;
   774→                    data[idx + 1] = g;
   775→                    data[idx + 2] = b;
   776→                    data[idx + 3] = a;
   777→                }
   778→
   779→                ctx.putImageData(imageData, 0, 0);
   780→            } catch (e) {
   781→                console.error('Error updating canvas:', e);
   782→            }
   783→        }
