  1167→                    shader2.delete();
  1168→                }
  1169→
  1170→                updateCanvasDisplay();
  1171→            },
  1172→
  1173→            mesh: () => {
  1174→                wasmCanvas.clear(0.05, 0.05, 0.05, 1.0);
  1175→
  1176→                // Get triangle vertices from parameters
  1177→                const v1x = getParam('mesh', 'triangle', 'v1x', 400);
  1178→                const v1y = getParam('mesh', 'triangle', 'v1y', 100);
  1179→                const v2x = getParam('mesh', 'triangle', 'v2x', 200);
  1180→                const v2y = getParam('mesh', 'triangle', 'v2y', 500);
  1181→                const v3x = getParam('mesh', 'triangle', 'v3x', 600);
  1182→                const v3y = getParam('mesh', 'triangle', 'v3y', 500);
  1183→
  1184→                // Get vertex colors from parameters
  1185→                const c1 = getColorParam('mesh', 'triangle', 'color1', '#ff0000');
  1186→                const c2 = getColorParam('mesh', 'triangle', 'color2', '#00ff00');
  1187→                const c3 = getColorParam('mesh', 'triangle', 'color3', '#0000ff');
  1188→
  1189→                // Create triangle mesh with vertex colors
  1190→                const verts = new Module.VectorFloat();
  1191→                const colors = new Module.VectorFloat();
  1192→                const indices = new Module.VectorInt();
  1193→
  1194→                // Triangle vertices
  1195→                [v1x, v1y, v2x, v2y, v3x, v3y].forEach(v => verts.push_back(v));
  1196→
  1197→                // Vertex colors (RGB + alpha)
  1198→                [c1.r, c1.g, c1.b, 1.0,
  1199→                 c2.r, c2.g, c2.b, 1.0,
  1200→                 c3.r, c3.g, c3.b, 1.0
  1201→                ].forEach(v => colors.push_back(v));
  1202→
  1203→                // Triangle indices
  1204→                [0, 1, 2].forEach(v => indices.push_back(v));
  1205→
  1206→                const paint = new Module.PaintWrapper();
  1207→                wasmCanvas.drawMesh(verts, colors, new Module.VectorFloat(), indices, paint);
  1208→
  1209→                verts.delete();
  1210→                colors.delete();
  1211→                indices.delete();
  1212→
  1213→                updateCanvasDisplay();
  1214→            },
  1215→
  1216→            'poly-spiral': () => {
  1217→                wasmCanvas.clear(1.0, 1.0, 1.0, 1.0);  // White background
  1218→
  1219→                // Fixed parameters for static demo
  1220→                const cx = 400;
  1221→                const cy = 300;
  1222→                const startSides = 3;
  1223→                const numPolygons = 16;
  1224→                const initialRadius = 60;
  1225→                const radiusGrowth = 16;
  1226→                const rotationPerLayer = 18;
  1227→
  1228→                // Color palette (vibrant colors matching the demo image) with semi-transparency
  1229→                const colorPalette = [
  1230→                    { r: 0.6, g: 0.9, b: 0.7, a: 0.85 },   // Light Green/Mint (center triangle)
  1231→                    { r: 0.3, g: 0.2, b: 0.7, a: 0.85 },   // Dark Purple
  1232→                    { r: 0.5, g: 0.9, b: 0.5, a: 0.85 },   // Light Green
  1233→                    { r: 0.4, g: 0.3, b: 0.8, a: 0.85 },   // Purple
  1234→                    { r: 0.9, g: 0.3, b: 0.8, a: 0.85 },   // Magenta
  1235→                    { r: 0.9, g: 0.9, b: 0.3, a: 0.85 },   // Yellow
  1236→                    { r: 0.2, g: 0.8, b: 0.8, a: 0.85 },   // Cyan
  1237→                    { r: 1.0, g: 0.6, b: 0.7, a: 0.85 },   // Light Pink
  1238→                    { r: 0.8, g: 0.3, b: 0.4, a: 0.85 }    // Dark Pink/Rose
  1239→                ];
  1240→
  1241→                // Draw from OUTSIDE to INSIDE so inner polygons appear on top
  1242→                for (let i = numPolygons - 1; i >= 0; i--) {
  1243→                    const sides = startSides + i;  // Each polygon has one more side
  1244→                    const radius = initialRadius + (i * radiusGrowth);  // Radius grows outward
  1245→                    const rotation = (rotationPerLayer * i * Math.PI) / 180;  // Accumulate rotation
  1246→
  1247→                    // Get color from palette (cycle through colors)
  1248→                    const color = colorPalette[i % colorPalette.length];
  1249→
  1250→                    // Create polygon points
  1251→                    const points = new Module.VectorFloat();
  1252→                    for (let v = 0; v < sides; v++) {
  1253→                        const angle = (v * 2 * Math.PI) / sides + rotation;
  1254→                        const x = radius * Math.cos(angle);
  1255→                        const y = radius * Math.sin(angle);
  1256→                        points.push_back(x);
  1257→                        points.push_back(y);
  1258→                    }
  1259→
  1260→                    // Draw polygon with transformation
  1261→                    wasmCanvas.save();
  1262→                    wasmCanvas.translate(cx, cy);
  1263→                    wasmCanvas.drawConvexPolygon(points, color.r, color.g, color.b, color.a);
  1264→                    wasmCanvas.restore();
  1265→
  1266→                    points.delete();
  1267→                }
  1268→
  1269→                updateCanvasDisplay();
  1270→            }
  1271→        };
  1272→
  1273→        // Initialize event handlers
  1274→        function initializeEventHandlers() {
  1275→            const controlsContainer = document.querySelector('.controls');
  1276→
  1277→            // Event delegation for all control inputs
  1278→            controlsContainer.addEventListener('input', (e) => {
  1279→                if (!e.target.dataset.param) return;
  1280→
  1281→                const paramName = e.target.dataset.param;
  1282→                const value = e.target.value;
  1283→
  1284→                // Update stored value
  1285→                currentParams[paramName] = value;
  1286→
  1287→                // Update display for range sliders
  1288→                if (e.target.type === 'range') {
  1289→                    const valueDisplay = document.getElementById(`${paramName}_value`);
  1290→                    if (valueDisplay) {
  1291→                        valueDisplay.textContent = value;
  1292→                    }
  1293→                }
  1294→
  1295→                // Update hex display for color pickers
  1296→                if (e.target.type === 'color') {
  1297→                    const hexDisplay = document.getElementById(`${paramName}_hex`);
  1298→                    if (hexDisplay) {
  1299→                        hexDisplay.value = value;
  1300→                    }
  1301→                }
  1302→
  1303→                // Trigger debounced render
  1304→                scheduleRender();
  1305→            });
  1306→
  1307→            // Change events for dropdowns (instant, no debounce)
  1308→            controlsContainer.addEventListener('change', (e) => {
  1309→                if (e.target.tagName === 'SELECT' && e.target.dataset.param) {
  1310→                    const paramName = e.target.dataset.param;
  1311→                    currentParams[paramName] = e.target.value;
  1312→                    scheduleRender();
  1313→                }
  1314→            });
  1315→
  1316→            // Demo preset selector
  1317→            document.getElementById('demoPreset').addEventListener('change', (e) => {
  1318→                currentDemo = e.target.value;
  1319→                updateDemoDescription(currentDemo);
  1320→
  1321→                // Generate new controls for selected demo
  1322→                const dynamicControls = document.getElementById('dynamicControls');
  1323→                dynamicControls.innerHTML = generateControlsForDemo(currentDemo);
  1324→
  1325→                // Run demo with new controls
  1326→                if (demos[currentDemo]) {
  1327→                    demos[currentDemo]();
  1328→                }
  1329→            });
  1330→
  1331→            // Clear button
  1332→            document.getElementById('clearBtn').addEventListener('click', () => {
  1333→                wasmCanvas.clear(1.0, 1.0, 1.0, 1.0);
  1334→                updateCanvasDisplay();
  1335→            });
  1336→        }
  1337→
  1338→        // Initialize WASM module
  1339→        GraphicsEngine().then((module) => {
  1340→            Module = module;
  1341→            wasmCanvas = new Module.CanvasWrapper(800, 600);
  1342→
  1343→            updateStatus('✅ Engine Ready!', 'success');
  1344→            canvas.style.display = 'block';
  1345→
  1346→            // Enable controls
  1347→            document.getElementById('demoPreset').disabled = false;
  1348→            document.getElementById('clearBtn').disabled = false;
  1349→
  1350→            // Initialize event handlers
  1351→            initializeEventHandlers();
  1352→
  1353→            // Generate initial controls and run initial demo
  1354→            const dynamicControls = document.getElementById('dynamicControls');
  1355→            dynamicControls.innerHTML = generateControlsForDemo(currentDemo);
  1356→            updateDemoDescription(currentDemo);
  1357→            if (demos[currentDemo]) {
  1358→                demos[currentDemo]();
  1359→            }
  1360→
  1361→        }).catch((error) => {
  1362→            updateStatus('❌ Failed to load WebAssembly module', 'error');
