              <div style={{ marginBottom: '3rem' }}>
                <h3 style={{ color: '#2E7D32', fontSize: '1.5rem', marginBottom: '0.5rem', paddingBottom: '0.5rem', borderBottom: '2px solid #2E7D32' }}>4. Paths & Curves</h3>
